    for bid, name, icon, color, hours, desc, cat in BIBLE_TOPICS:
        bibles.append({
            "id": bid, "name": name, "icon": icon, "color": color,
            "total_hours": hours, "category": "bible",
            "description": desc,
            "sections": [{
                "id": f"{bid}_s1", "name": f"{name} Fundamentals",
                "articles": [{
                    "id": f"{bid}_a1", "title": f"{name} — Core Concepts",
                    "content": f"# {name}\n\n{desc}\n\nThis bible covers everything from fundamentals to advanced production patterns.",
                    "tags": [cat, "fundamentals"], "difficulty": "beginner",
                }],
                "article_count": 1,
            }, {
                "id": f"{bid}_s2", "name": f"Advanced {name.replace(' Bible','')}",
                "articles": [{
                    "id": f"{bid}_a2", "title": f"Advanced Patterns & Best Practices",
                    "content": f"# Advanced {name.replace(' Bible','')}\n\nProduction-grade patterns, optimization techniques, and real-world architecture decisions.",
                    "tags": [cat, "advanced"], "difficulty": "advanced",
                }, {
                    "id": f"{bid}_a3", "title": f"Reference & Cheat Sheet",
                    "content": f"# {name.replace(' Bible','')} Quick Reference\n\nComprehensive cheat sheet with common patterns, commands, and configurations.",
                    "tags": [cat, "reference", "cheat-sheet"], "difficulty": "intermediate",
                }],
                "article_count": 2,
            }],
        })
    return bibles


