def get_mega_challenges():
    challenges = []
    for cid, title, diff, cat, tags, desc, sol in CHALLENGE_TEMPLATES:
        challenges.append({
            "id": cid, "title": title, "difficulty": diff, "category": cat,
            "description": desc, "examples": [{"input": "See problem", "output": "See solution"}],
            "constraints": ["Standard constraints apply"],
            "hints": [sol], "solution": f"# {title}\n# {sol}",
            "test_cases": [], "tags": tags,
        })
    return challenges


